INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8525, 'ផលធៀបរវាងផ្ទៃក្រឡារង្វង់កាំ \(r\) និងការេជ្រុង \(x\) គឺ៖', NULL, '["\\(\\dfrac{2\\pi r}{4x}\\)", "\\(\\dfrac{\\pi r}{x}\\)", "\\(\\dfrac{\\pi r^2}{x^2}\\)", "\\(\\dfrac{r^2}{\\pi x^2}\\)"]', 2, NULL, 3, 'mcq', '\(\mathcal{A}_{\text{រង្វង់}} = \pi r^2\) ; \(\mathcal{A}_{\text{ការេ}} = x^2\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8526, 'តម្លៃ \(x\) ណាធ្វើឱ្យ \(\dfrac{(x-5)(2x-1)-x+5}{x^2-4}\) ស្មើសូន្យ?', NULL, '["\\(x = \\pm 2\\)", "\\(x = 1\\) ឬ \\(x = -5\\)", "\\(x = 5\\) ឬ \\(x = 1\\)", "\\(x = 5\\) ឬ \\(x = \\tfrac12\\)"]', 2, NULL, 3, 'mcq', 'ភាគយក \((x-5)(2x-1) - (x-5) = 2(x-5)(x-1)\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8527, 'សម្រួល \(\dfrac{3a^{3}-3a^{2}-6a}{6a^{3}-12a^{2}-18a}\) ៖', NULL, '["\\(\\dfrac{2 \\left(a - 3\\right)}{a - 2}\\)", "\\(\\dfrac{a + 2}{2 \\left(a + 3\\right)}\\)", "\\(\\dfrac{a - 2}{2 \\left(a - 3\\right)}\\)", "\\(- \\dfrac{a - 2}{2 \\left(a - 3\\right)}\\)"]', 2, NULL, 3, 'mcq', 'ដាក់ជាផលគុណកត្តា រួចសម្រួល ៖ \(\dfrac{a - 2}{2 \left(a - 3\right)}\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8528, 'គណនាផលគុណ \(\dfrac{9a^{2}-6a+1}{5-a} \times \dfrac{5(a-2)-a(a-2)}{a^{2}-4a+4}\) ៖', NULL, '["\\(\\dfrac{a - 2}{\\left(3 a - 1\\right)^{2}}\\)", "\\(- \\dfrac{\\left(3 a - 1\\right)^{2}}{a - 2}\\)", "\\(\\dfrac{\\left(3 a - 1\\right)^{2}}{a - 2}\\)", "\\(- \\dfrac{\\left(3 a + 1\\right)^{2}}{a + 2}\\)"]', 2, NULL, 3, 'mcq', 'ដាក់ជាផលគុណកត្តា រួចសម្រួល ៖ \(\dfrac{\left(3 a - 1\right)^{2}}{a - 2}\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8529, 'គណនា \(\dfrac{t+1}{t^{2}+5t} + \dfrac{8}{t^{2}-25}\) ៖', NULL, '["\\(\\dfrac{t - 1}{t \\left(t - 5\\right)}\\)", "\\(- \\dfrac{t - 1}{t \\left(t - 5\\right)}\\)", "\\(- \\dfrac{t + 1}{t \\left(t + 5\\right)}\\)", "\\(\\dfrac{t \\left(t - 5\\right)}{t - 1}\\)"]', 0, NULL, 3, 'mcq', 'ដាក់ជាផលគុណកត្តា រួចសម្រួល ៖ \(\dfrac{t - 1}{t \left(t - 5\right)}\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8530, 'កន្សោម \(\dfrac{1}{a^3-a}\) គ្មានន័យ ពេល៖', NULL, '["\\(a = 0\\) តែប៉ុណ្ណោះ", "\\(a = 1,\\ -1\\)", "\\(a = 0,\\ 1\\)", "\\(a = 0,\\ 1,\\ -1\\)"]', 3, NULL, 3, 'mcq', '\(a^3 - a = a(a-1)(a+1)\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8531, 'សម្រួល \(\dfrac{x-y}{x^{2}+xz-xy-zy}\) ៖', NULL, '["\\(x + z\\)", "\\(\\dfrac{1}{x + z}\\)", "\\(- \\dfrac{1}{x - z}\\)", "\\(- \\dfrac{1}{x + z}\\)"]', 1, NULL, 3, 'mcq', 'ដាក់ជាផលគុណកត្តា រួចសម្រួល ៖ \(\dfrac{1}{x + z}\)។', 'កន្សោមសនិទាន', 'hard', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
