INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8532, 'ចតុកោណកែងមានវិមាត្រ \(x\) និង \(y\) ដូចរូប។ ផលធៀបរវាងផ្ទៃក្រឡានិងបរិមាត្រគឺ៖', 'g8-a6eb1194e3.svg', '["\\(\\dfrac{xy}{x+y}\\)", "\\(\\dfrac{xy}{2(x+y)}\\)", "\\(\\dfrac{2(x+y)}{xy}\\)", "\\(\\dfrac{x+y}{xy}\\)"]', 1, NULL, 3, 'mcq', '\(\mathcal{A} = xy\) ; \(P = 2(x+y)\)។', 'កន្សោមសនិទាន', 'pisa', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
