INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8533, 'អ្នកដើរចម្ងាយ \(12\ \text{km}\) ក្នុងល្បឿន \(x\ \text{km/h}\) ហើយត្រឡប់មកវិញក្នុងល្បឿន \((x+2)\ \text{km/h}\)។ ពេលសរុប (ម៉ោង) គឺ៖', 'g8-15b0094ae4.svg', '["\\(\\dfrac{24}{2x+2}\\)", "\\(\\dfrac{24(x+1)}{x(x+2)}\\)", "\\(\\dfrac{12}{x} - \\dfrac{12}{x+2}\\)", "\\(\\dfrac{24}{x(x+2)}\\)"]', 1, NULL, 3, 'mcq', '\(\dfrac{12}{x} + \dfrac{12}{x+2} = \dfrac{12(x+2)+12x}{x(x+2)} = \dfrac{24(x+1)}{x(x+2)}\)។', 'កន្សោមសនិទាន', 'pisa', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-273f42f62c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8534, 'រង្វង់មួយចារឹកក្នុងការេជ្រុង \(x\)។ ផលធៀបរវាងផ្ទៃក្រឡារង្វង់និងការេគឺ៖', 'g8-273f42f62c.svg', '["\\(\\dfrac{\\pi}{4}\\)", "\\(\\dfrac{\\pi}{2}\\)", "\\(\\pi\\)", "\\(\\dfrac{4}{\\pi}\\)"]', 0, NULL, 3, 'mcq', '\(r = \dfrac{x}{2}\) ; \(\dfrac{\pi (x/2)^2}{x^2} = \dfrac{\pi}{4}\)។', 'កន្សោមសនិទាន', 'pisa', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8535, 'អ្នកដើរចម្ងាយ \(12\ \text{km}\) ក្នុងល្បឿន \(4\ \text{km/h}\) ហើយត្រឡប់មកវិញក្នុងល្បឿន \(6\ \text{km/h}\)។ ពេលធ្វើដំណើរសរុបគឺ៖', NULL, '["\\(5\\) ម៉ោង", "\\(3\\) ម៉ោង", "\\(4.8\\) ម៉ោង", "\\(6\\) ម៉ោង"]', 0, NULL, 3, 'mcq', '\(\dfrac{12}{4} + \dfrac{12}{6} = 3 + 2 = 5\)។', 'កន្សោមសនិទាន', 'pisa', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8536, 'គណនា \(S = \dfrac{1}{1\times2} + \dfrac{1}{2\times3} + \dfrac{1}{3\times4} + \dfrac{1}{4\times5}\) ដោយប្រើ \(\dfrac{1}{n(n+1)} = \dfrac{1}{n} - \dfrac{1}{n+1}\)៖', NULL, '["\\(\\dfrac{1}{5}\\)", "\\(\\dfrac{9}{20}\\)", "\\(\\dfrac{5}{4}\\)", "\\(\\dfrac{4}{5}\\)"]', 3, NULL, 3, 'mcq', '\(S = 1 - \dfrac{1}{5} = \dfrac{4}{5}\)។', 'កន្សោមសនិទាន', 'pisa', 1, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8537, 'គេមានកន្សោម \(\dfrac{3x}{x-2}\)។ គណនាតម្លៃលេខ ចំពោះ \(x = -1\), \(x = 0\), \(x = 2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួសតម្លៃ \(x = -1\) ៖ \(\dfrac{3(-1)}{-1-2} = \dfrac{-3}{-3} = 1\) (2 ពិន្ទុ)
\(x = 0\) ៖ \(\dfrac{0}{-2} = 0\) (1 ពិន្ទុ)
\(x = 2\) ៖ ភាគបែង \(2 - 2 = 0\) (1 ពិន្ទុ)
ដូចនេះកន្សោមគ្មានន័យ (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'easy', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8538, 'គេមានកន្សោម \(\dfrac{a-5}{2a+6}\)។ កំណត់ \(a\) ដើម្បីឱ្យកន្សោម ក. គ្មានន័យ ខ. ស្មើសូន្យ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គ្មានន័យ លុះត្រាតែភាគបែងស្មើ \(0\) (1 ពិន្ទុ)
\(2a + 6 = 0 \Rightarrow a = -3\) (1 ពិន្ទុ)
ខ. ស្មើសូន្យ លុះត្រាតែភាគយកស្មើ \(0\) និងភាគបែងខុសពីសូន្យ (1 ពិន្ទុ)
\(a - 5 = 0 \Rightarrow a = 5\) (1 ពិន្ទុ)
ត្រួតពិនិត្យ \(2(5) + 6 = 16 \neq 0\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'medium', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8539, 'សម្រួល ក. \(\dfrac{2x-6}{5x-15}\) ខ. \(\dfrac{3x^{2}+4x}{9x^{2}-16}\) គ. \(\dfrac{a^{2}+4a-12}{a^{2}+2a-8}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{2(x-3)}{5(x-3)} = \dfrac{2}{5}\) (1 ពិន្ទុ)
ខ. \(\dfrac{x(3x+4)}{(3x-4)(3x+4)}\) (1 ពិន្ទុ)
\(= \dfrac{x}{3 x - 4}\) (1 ពិន្ទុ)
គ. \(\dfrac{(a+6)(a-2)}{(a+4)(a-2)}\) (1 ពិន្ទុ)
\(= \dfrac{a + 6}{a + 4}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'medium', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8540, 'គណនាផលគុណ \(\dfrac{7b}{10a} \times \dfrac{5a^{2}}{8b}\) និង \(\dfrac{5x}{4x-12} \times \dfrac{2x^{2}-6x}{3}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{7b \cdot 5a^2}{10a \cdot 8b} = \dfrac{35a^2 b}{80ab}\) (1 ពិន្ទុ)
\(= \dfrac{7 a}{16}\) (1 ពិន្ទុ)
ខ. \(\dfrac{5x}{4(x-3)} \times \dfrac{2x(x-3)}{3}\) (1 ពិន្ទុ)
\(= \dfrac{10x^2(x-3)}{12(x-3)}\) (1 ពិន្ទុ)
\(= \dfrac{5 x^{2}}{6}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'medium', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8541, 'គណនា ក. \(\dfrac{y}{2x} + \dfrac{x}{3y}\) ខ. \(\dfrac{4}{n} - \dfrac{2}{n+1}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ភាគបែងរួមតូចបំផុត \(6xy\) (1 ពិន្ទុ)
\(\dfrac{3y^2 + 2x^2}{6xy}\) (1 ពិន្ទុ)
ខ. ភាគបែងរួម \(n(n+1)\) (1 ពិន្ទុ)
\(\dfrac{4(n+1) - 2n}{n(n+1)} = \dfrac{2n+4}{n(n+1)}\) (1 ពិន្ទុ)
\(= \dfrac{2(n+2)}{n(n+1)}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'medium', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8542, 'សម្រួល \(\dfrac{(x-3)(3x+1)-(2x-6)(x+1)}{1-x^{2}}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កត្តា \(2x - 6 = 2(x-3)\) ; \(1 - x^2 = -(x-1)(x+1)\) (1 ពិន្ទុ)
ភាគយក \((x-3)[(3x+1) - 2(x+1)] = (x-3)(x-1)\) (2 ពិន្ទុ)
\(\dfrac{(x-3)(x-1)}{-(x-1)(x+1)}\) (1 ពិន្ទុ)
\(= -\dfrac{x-3}{x+1}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'hard', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8543, 'គណនាផលចែក \(\dfrac{4x^{2}+8x}{x^{2}-9} \div \dfrac{6x^{3}+12x^{2}}{x^{2}-2x-3}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កត្តា \(4x(x+2)\) ; \((x-3)(x+3)\) ; \(6x^2(x+2)\) ; \((x-3)(x+1)\) (2 ពិន្ទុ)
គុណនឹងចម្រាស \(\dfrac{4x(x+2)}{(x-3)(x+3)} \times \dfrac{(x-3)(x+1)}{6x^2(x+2)}\) (1 ពិន្ទុ)
\(= \dfrac{2 \left(x + 1\right)}{3 x \left(x + 3\right)}\) (2 ពិន្ទុ)', 'កន្សោមសនិទាន', 'hard', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8544, 'គណនា \(\dfrac{t+1}{t^{2}+5t} + \dfrac{8}{t^{2}-25}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាគបែង \(t(t+5)\) និង \((t-5)(t+5)\) ភាគបែងរួម \(t(t+5)(t-5)\) (1 ពិន្ទុ)
\(\dfrac{(t+1)(t-5) + 8t}{t(t+5)(t-5)} = \dfrac{t^2 + 4t - 5}{t(t+5)(t-5)}\) (2 ពិន្ទុ)
\(= \dfrac{(t+5)(t-1)}{t(t+5)(t-5)} = \dfrac{t-1}{t(t-5)}\) (2 ពិន្ទុ)', 'កន្សោមសនិទាន', 'hard', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8545, 'ក. បង្ហាញថា \(\dfrac{1}{n} - \dfrac{1}{n+1} = \dfrac{1}{n(n+1)}\)។ ខ. គណនា \(S = \dfrac{1}{1\times2} + \dfrac{1}{2\times3} + \dfrac{1}{3\times4} + \dfrac{1}{4\times5}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{(n+1) - n}{n(n+1)}\) (1 ពិន្ទុ)
\(= \dfrac{1}{n(n+1)}\) (1 ពិន្ទុ)
ខ. សរសេរ \(S = (1 - \tfrac12) + (\tfrac12 - \tfrac13) + (\tfrac13 - \tfrac14) + (\tfrac14 - \tfrac15)\) (1 ពិន្ទុ)
ពាក្យកណ្តាលលុបគ្នា (1 ពិន្ទុ)
\(S = 1 - \dfrac{1}{5} = \dfrac{4}{5}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'hard', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8546, 'រង្វង់មួយចារឹកក្នុងការេជ្រុង \(x\)។ ក. រកកាំរង្វង់។ ខ. រកផ្ទៃក្រឡារង្វង់ និងការេ។ គ. រកផលធៀបរវាងផ្ទៃក្រឡារង្វង់និងការេ។', 'g8-273f42f62c.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(r = \dfrac{x}{2}\) (1 ពិន្ទុ)
ខ. \(\mathcal{A}_{\text{រង្វង់}} = \pi\left(\dfrac{x}{2}\right)^2 = \dfrac{\pi}{4}x^2\) (1 ពិន្ទុ)
\(\mathcal{A}_{\text{ការេ}} = x^2\) (1 ពិន្ទុ)
គ. \(\dfrac{\pi x^2 / 4}{x^2}\) (1 ពិន្ទុ)
\(= \dfrac{\pi}{4}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'pisa', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8547, 'អ្នកដើរចម្ងាយ \(12\ \text{km}\) ក្នុងល្បឿន \(x\ \text{km/h}\) ហើយត្រឡប់ក្នុងល្បឿន \((x+2)\ \text{km/h}\)។ ក. សរសេរពេលសរុបជាកន្សោមសនិទានសម្រួលរួច។ ខ. គណនាពេលសរុប ពេល \(x = 4\)។', 'g8-15b0094ae4.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(t_1 = \dfrac{12}{x}\) ; \(t_2 = \dfrac{12}{x+2}\) (1 ពិន្ទុ)
\(\dfrac{12(x+2) + 12x}{x(x+2)} = \dfrac{24x + 24}{x(x+2)}\) (1 ពិន្ទុ)
\(= \dfrac{24(x+1)}{x(x+2)}\) (1 ពិន្ទុ)
ខ. \(\dfrac{24 \times 5}{4 \times 6} = \dfrac{120}{24}\) (1 ពិន្ទុ)
\(= 5\) ម៉ោង (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'pisa', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8548, 'ចតុកោណកែងមានវិមាត្រ \(x\) និង \(y\)។ ក. សរសេរផ្ទៃក្រឡានិងបរិមាត្រ។ ខ. សរសេរផលធៀបរវាងផ្ទៃក្រឡានិងបរិមាត្រជាកន្សោមសនិទាន។ គ. គណនាផលធៀប ពេល \(x = 6, y = 3\)។', 'g8-a6eb1194e3.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(\mathcal{A} = xy\) ; \(P = 2(x+y)\) (2 ពិន្ទុ)
ខ. \(\dfrac{\mathcal{A}}{P} = \dfrac{xy}{2(x+y)}\) (1 ពិន្ទុ)
គ. \(\dfrac{6 \times 3}{2(6+3)} = \dfrac{18}{18}\) (1 ពិន្ទុ)
\(= 1\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'pisa', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8549, 'ផលធៀបនៃចំនួនគត់ \(n\) និងចំនួនគត់បន្ទាប់ជាកន្សោមសនិទាន។ ក. សរសេរកន្សោមនោះ។ ខ. កំណត់ \(n\) ដែលកន្សោមស្មើ \(\dfrac{4}{5}\)។ គ. កំណត់តម្លៃ \(n\) ដែលកន្សោមគ្មានន័យ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{n}{n+1}\) (1 ពិន្ទុ)
ខ. \(\dfrac{n}{n+1} = \dfrac{4}{5} \Rightarrow 5n = 4(n+1)\) (2 ពិន្ទុ)
\(n = 4\) (1 ពិន្ទុ)
គ. ភាគបែង \(n + 1 = 0 \Rightarrow n = -1\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'pisa', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8550, 'ចតុកោណកែងមួយមានផ្ទៃក្រឡា \(x^2 - 9\) និងទទឹង \(x + 3\)។ ក. រកបណ្តោយជាកន្សោមសនិទានសម្រួលរួច។ ខ. សរសេរផលធៀបបណ្តោយនិងទទឹង។ គ. គណនាផលធៀប ពេល \(x = 7\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បណ្តោយ \(\dfrac{x^2 - 9}{x + 3} = \dfrac{(x-3)(x+3)}{x+3}\) (1 ពិន្ទុ)
\(= x - 3\) (1 ពិន្ទុ)
ខ. \(\dfrac{\text{បណ្តោយ}}{\text{ទទឹង}} = \dfrac{x-3}{x+3}\) (1 ពិន្ទុ)
គ. \(\dfrac{7-3}{7+3} = \dfrac{4}{10}\) (1 ពិន្ទុ)
\(= \dfrac{2}{5}\) (1 ពិន្ទុ)', 'កន្សោមសនិទាន', 'pisa', 0, '8', 'កន្សោមសនិទាន', NULL, 0);
